window.__votdWeek && window.__votdWeek({"week":"2029-03-26","reading":"","days":[{"d":"2029-03-26","ref":"D&C 19:16","b":"D&C","c":19,"v":16,"he":"כִּי הִנֵּה אָנֹכִי אֱלֹהִים סָבַלְתִּי אֶת־אֵלֶּה בְּעַד כֻּלָּם לְמַעַן לֹא יִסְבְּלוּ אִם יָשׁוּבוּ׃","en":"For behold, I, God, have suffered these things for all, that they might not suffer if they would repent;"},{"d":"2029-03-27","ref":"D&C 19:18","b":"D&C","c":19,"v":18,"he":"וְהַסֵּבֶל הַהוּא הֱבִיאַנִי אָנֹכִי אֱלֹהִים הַגָּדוֹל מִכֹּל לִרְעֹד מִכְּאֵב וְלָזוּב דָּם מִכׇּל־נְקָב בִּבְשָׂרִי וְלִסְבֹּל בַּגּוּף וּבָרוּחַ וְאָבִיתִי לְבִלְתִּי שְׁתוֹת אֶת־הַכּוֹס הַמָּרָה וְאֶסּוֹג׃","en":"Which suffering caused myself, even God, the greatest of all, to tremble because of pain, and to bleed at every pore, and to suffer both body and spirit—and would that I might not drink the bitter cup, and shrink—"},{"d":"2029-03-28","ref":"D&C 19:19","b":"D&C","c":19,"v":19,"he":"אַךְ כָּבוֹד לָאָב וָאֶשְׁתֶּה וְכִלִּיתִי אֶת־אֲשֶׁר הֲכִינוֹתִי לִבְנֵי הָאָדָם׃","en":"Nevertheless, glory be to the Father, and I partook and finished my preparations unto the children of men."},{"d":"2029-03-29","ref":"D&C 76:22","b":"D&C","c":76,"v":22,"he":"וְעַתָּה אַחֲרֵי עֵדֻיּוֹת רַבּוֹת אֲשֶׁר נִתְּנוּ עָלָיו זֹאת הָעֵדוּת הָאַחֲרוֹנָה אֲשֶׁר אֲנַחְנוּ מְעִידִים עָלָיו כִּי הוּא חָי׃","en":"And now, after the many testimonies which have been given of him, this is the testimony, last of all, which we give of him: That he lives!"},{"d":"2029-03-30","ref":"D&C 76:23","b":"D&C","c":76,"v":23,"he":"כִּי רְאִינוּהוּ גַּם לִימִין אֱלֹהִים וְשָׁמַעְנוּ אֶת־הַקּוֹל מֵעִיד כִּי הוּא יְחִיד הָאָב׃","en":"For we saw him, even on the right hand of God; and we heard the voice bearing record that he is the Only Begotten of the Father—"},{"d":"2029-03-31","ref":"D&C 76:24","b":"D&C","c":76,"v":24,"he":"כִּי עַל יָדוֹ וּבְיָדוֹ וּמִמֶּנּוּ הָעוֹלָמוֹת נִבְרָאִים וְיוֹשְׁבֵיהֶם הֵם נוֹלָדִים בָּנִים וּבָנוֹת לֵאלֹהִים׃","en":"That by him, and through him, and of him, the worlds are and were created, and the inhabitants thereof are begotten sons and daughters unto God."},{"d":"2029-04-01","ref":"D&C 88:6","b":"D&C","c":88,"v":6,"he":"הוּא אֲשֶׁר עָלָה לַמָּרוֹם וְגַם יָרַד לְמַטָּה מִכֹּל בַּאֲשֶׁר הֵבִין אֶת־הַכֹּל לְמַעַן יִהְיֶה בַּכֹּל וּבְתוֹךְ הַכֹּל אוֹר הָאֱמֶת׃","en":"He that ascended up on high, as also he descended below all things, in that he comprehended all things, that he might be in all and through all things, the light of truth;"}]});
